export const inject = ['systemPrompt']

export function apply(ctx, config = {}) {
  // ...读取 enabled/content/order/name

插件只做一件事：在 `systemPrompt` 服务上注册一个静态章节。它不读取会话、不写文件、
不注册工具、不发起网络请求，也不保存任何状态。

